{
  "name": "@fish-under-sea/opencode-meoo-auth",
  "version": "1.2.1",
  "description": "Meoo 秒悟 (meoo.com) in OpenCode and Magpie: PKCE sign-in, reuse of a local dsh-meoo-connect state or a project service AK, a live catalog with each model's real context window, and the account's points balance",
  "type": "module",
  "main": "./opencode.mjs",
  "exports": {
    ".": "./opencode2.mjs"
  },
  "files": [
    "index.mjs",
    "opencode.mjs",
    "opencode2.mjs",
    "README.md",
    "LICENSE",
    "THIRD_PARTY_NOTICES.md"
  ],
  "scripts": {
    "test": "node --test test/offline.test.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-provider",
    "meoo",
    "秒悟",
    "openai-compatible"
  ],
  "license": "MIT",
  "author": {
    "name": "Fish-under-sea",
    "url": "https://github.com/Fish-under-sea"
  },
  "contributors": [
    {
      "name": "Chensy (elysia395)",
      "url": "https://github.com/elysia395"
    }
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Fish-under-sea/opencode-meoo-auth.git"
  },
  "homepage": "https://github.com/Fish-under-sea/opencode-meoo-auth#readme",
  "bugs": {
    "url": "https://github.com/Fish-under-sea/opencode-meoo-auth/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "magpie": {
    "name": "Meoo",
    "summary": {
      "en": "Meoo 秒悟 (meoo.com) in magpie: sign in with your own Meoo account and its gateway's models show up as one provider, with usage-billed tokens.",
      "zh": "用自己的 Meoo 秒悟账号使用 Meoo 网关上的模型——浏览器 PKCE 授权、复用本机登录态或项目服务 AK，模型目录实时同步。"
    },
    "icon": "data:image/png;base64,"
  }
}
